'use strict';

// MODULES //

import Complex64 from '@stdlib/complex-float32-ctor';
import copysignf from '@stdlib/math-base-special-copysignf';
import { assign as sincosf } from '@stdlib/math-base-special-sincosf';
import isnanf from '@stdlib/math-base-assert-is-nanf';
import isInfinitef from '@stdlib/math-base-assert-is-infinitef';
import expf from '@stdlib/math-base-special-expf';
import f32 from '@stdlib/number-float64-base-to-float32';
import PINF from '@stdlib/constants-float32-pinf';
import NINF from '@stdlib/constants-float32-ninf';
import realf from '@stdlib/complex-float32-real';
import imagf from '@stdlib/complex-float32-imag';


// VARIABLES //

var WORKSPACE = [ 0.0, 0.0 ];


// MAIN //

/**
* Evaluates the exponential function for a single-precision complex floating-point number.
*
* @param {Complex64} z - complex number
* @returns {Complex64} result
*
* @example
* import Complex64 from '@stdlib/complex-float32-ctor';
* import cexpf from '@stdlib/math-base-special-cexpf';
*
* var v = cexpf( new Complex64( 0.0, 0.0 ) );
* // returns <Complex64>[ 1.0, 0.0 ]
*
* @example
* import Complex64 from '@stdlib/complex-float32-ctor';
* import cexpf from '@stdlib/math-base-special-cexpf';
*
* var v = cexpf( new Complex64( 1.0, 0.0 ) );
* // returns <Complex64>[ ~2.718, 0.0 ]
*/
function cexpf( z ) {
	var im;
	var re;
	var e;

	re = realf( z );
	im = imagf( z );

	if ( isnanf( re ) ) {
		re = NaN;
		im = ( im === 0.0 ) ? im : re;
	} else if ( isInfinitef( im ) ) {
		if ( re === PINF ) {
			re = -re;
			im = NaN;
		} else if ( re === NINF ) {
			re = -0.0;
			im = copysignf( 0.0, im );
		} else {
			re = NaN;
			im = NaN;
		}
	} else {
		e = expf( re );
		if ( im === 0.0 ) {
			re = e;
		} else {
			sincosf( im, WORKSPACE, 1, 0 );
			re = f32( WORKSPACE[ 1 ] * e );
			im = f32( WORKSPACE[ 0 ] * e );
		}
	}
	return new Complex64( re, im );
}


// EXPORTS //

export default cexpf;
